## 模拟经营变量格式

Model json结构：
```ts
interface Property {
    "str": number, // Strength
    "dex": number, // Dexterity
    "con": number, // Constitution
    "int": number, // Intelligence
    "wis": number, // Wisdom
    "cha": number, // Charisma
}

export interface Model {
    "user": {
        "name": string,
        "desc": string,
        "avatar": string, // png url
        "property": Property
    },
    "charas": Record<string, {
        "name": string,
        "desc": string,
        "relation": string,
        "status": string,
        "avatar": string, // png url
        "property": Property
    }>,
    "buildings": Record<string, {
        "name": string,
        "type": string,
        "level": number,
        "status": string,
        "desc": string
    }>,
    "items": Record<string, {
        "name": string,
        "type": string,
        "status": string,
        "desc": string
    }>,
}

```

示例：
```json
{
  "user": {
    "name": "张三",
    "desc": "一个平凡的普通人",
    "avatar": "https://93.png",
    "property": {
      "str": 23,
      "dex": -94,
      "con": 51,
      "int": 61,
      "wis": 31,
      "cha": 41
    }
  },
  "charas": {
    "李四": {
      "name": "李四",
      "desc": "一个不平凡的普通人",
      "avatar": "https://dd.png",
      "relation": "敌对",
      "status": "健康",
      "property": {
        "str": 78,
        "dex": 45,
        "con": 60,
        "int": 30,
        "wis": 22,
        "cha": 15
      }
    }
  },
  "buildings": {
    "仓库": {
      "name": "仓库",
      "type": "仓储",
      "level": 2,
      "status": "运作中",
      "desc": "用废弃集装箱改造的仓库，堆满了 scavenge 来的物资，铁皮上还留着丧尸的血迹"
    }
  },
  "items": {
    "铁锹": {
      "name": "铁锹",
      "type": "工具",
      "desc": "一把生锈的铁锹，手柄上缠着破布，勉强能用",
      "status": "手柄松动"
    }
  }
}

```

styles.content:
/* 浅色主题 */
:root {
    --bg: #ffffff;
    --panel: #f8f9fa;
    --card: #f0f1f3;
    --border: #e0e0e0;
    --text: #222222;
    --text2: #666666;
    --text3: #999999;
    --accent: #0891b2;
    --red: #dc2626;
    --orange: #ea580c;
    --green: #16a34a;
    --blue: #2563eb;
    --font: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
    --mono: 'Cascadia Code', 'Consolas', monospace;
    --avatar-status-color: var(--green);
}

/* 页面根容器 */
#sim-app {
    color: var(--text);
    font-family: var(--font);
    font-size: 14px;
}

/* 浮动面板 */
.sim-panel {
    width: 360px;
    max-width: 100vw;
    height: 720px;
    max-height: 100vh;
    display: flex;
    flex-direction: column;
    padding: 14px;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
    box-shadow: 0 2px 12px rgba(0, 0, 0, .08);
}

/* 身份卡 */
.profile-card {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 12px 14px;
    margin-bottom: 14px;
    background: rgba(8, 145, 178, .04);
    border: 1px solid rgba(8, 145, 178, .15);
    border-radius: 10px;
}

.profile-avatar {
    flex: none;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    border: 2px solid var(--border);
    border-radius: 4px;
}

.profile-avatar::after {
    content: '';
    position: absolute;
    top: -9px;
    left: -9px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--avatar-status-color);
    border: 2px solid var(--panel);
    animation: pulse-dot 2s ease-in-out infinite;
}

.profile-avatar-img {
    display: block;
    width: 128px;
    height: auto;
}

.profile-avatar-fallback {
    width: 60px;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--accent);
    color: #fff;
    font-size: 24px;
    font-weight: 700;
    font-family: var(--mono);
}

.profile-info {
    flex: 1;
    min-width: 0;
    position: relative;
    padding-left: 10px;
}

.profile-info::before {
    content: '';
    position: absolute;
    left: 0;
    top: 4px;
    bottom: 4px;
    width: 2px;
    background-color: var(--accent);
    border-radius: 1px;
}

@keyframes pulse-dot {
    0%, 100% {
        opacity: 1;
    }
    50% {
        opacity: .3;
    }
}

.profile-name {
    font-size: 16px;
    font-weight: 700;
    color: var(--text);
    letter-spacing: 1px;
}

.profile-desc {
    font-size: 11px;
    color: var(--text2);
    margin-top: 6px;
}

/* 属性卡片 */
.property-card {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.property-items {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
    gap: 6px;
    flex: 1;
}

.property-item {
    display: flex;
    align-items: center;
    gap: 8px;
}

.property-label {
    width: 32px;
    font-size: 12px;
    font-weight: 600;
    color: var(--accent);
    text-align: right;
    flex: none;
    font-family: var(--mono);
}

.property-progress {
    flex: 1;
    height: 4px;
    background: var(--card);
    border-radius: 1px;
    overflow: hidden;
    position: relative;
}

.property-progress::before {
    content: '';
    position: absolute;
    left: 50%;
    top: 0;
    width: 1px;
    height: 100%;
    background: var(--border);
    transform: translateX(-0.5px);
}

.property-progress-bar {
    position: absolute;
    left: 50%;
    top: 0;
    height: 100%;
    width: calc(var(--percentage, 0) * 0.5%);
    background: linear-gradient(90deg, var(--blue), var(--accent));
    border-radius: 0 4px 4px 0;
    transition: width .3s;
}

.property-progress-bar.reverse {
    left: auto;
    right: 50%;
    background: linear-gradient(270deg, var(--red), #fca5a5);
    border-radius: 4px 0 0 4px;
}

.property-value {
    width: 36px;
    font-size: 13px;
    font-weight: 700;
    color: var(--text);
    text-align: right;
    font-family: var(--mono);
    flex: none;
}

/* 雷达图容器 */
.property-radar {
    width: 200px;
    height: 200px;
    align-self: center;
}

/* ===== 角色列表 ===== */
.charas-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.chara-relation {
    flex: none;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border: 1px solid;
    border-radius: 4px;
    background: rgba(255, 255, 255, .5);
    white-space: nowrap;
}

.chara-status-tag {
    flex: none;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border: 1px solid;
    border-radius: 4px;
    background: rgba(255, 255, 255, .4);
    white-space: nowrap;
}

.chara-empty {
    text-align: center;
    padding: 30px 20px;
    color: var(--text3);
}

.chara-empty-icon {
    font-size: 36px;
    margin-bottom: 8px;
    opacity: .4;
}

.chara-empty-text {
    font-size: 13px;
}

/* ===== 建筑总览 ===== */
.build-root {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.build-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
}

.build-filter-btn {
    padding: 4px 10px;
    font-size: 11px;
    font-family: inherit;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: transparent;
    color: var(--text2);
    cursor: pointer;
    transition: all .15s;
    white-space: nowrap;
}

.build-filter-btn:hover {
    color: var(--text);
    background: var(--card);
}

.build-filter-btn.active {
    border-color: var(--accent);
    color: var(--accent);
    background: rgba(8, 145, 178, .06);
}

.build-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.build-type-dot {
    flex: none;
    font-size: 16px;
    line-height: 1;
}


.build-level {
    flex: none;
    font-size: 10px;
    font-weight: 700;
    font-family: var(--mono);
    color: var(--text3);
    background: var(--panel);
    padding: 1px 6px;
    border-radius: 4px;
}

.build-status-tag {
    flex: none;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border: 1px solid;
    border-radius: 4px;
    white-space: nowrap;
}

.build-desc {
    font-size: 12px;
    color: var(--text2);
    line-height: 1.7;
    padding: 8px 10px;
    background: rgba(0, 0, 0, .02);
    border-radius: 6px;
    border-left: 2px solid var(--accent);
}

.build-empty {
    text-align: center;
    padding: 30px 20px;
    color: var(--text3);
}

/* ===== 物品 ===== */
.item-status-tag {
    flex: none;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border: 1px solid;
    border-radius: 4px;
    white-space: nowrap;
}

